def words_in_sentence(sentence):
    """
    Return a string containing the words from the original sentence whose lengths are prime numbers,
    preserving their order.

    Parameters:
    - sentence: str, input sentence with words separated by spaces

    Returns:
        A string of words (joined by space) that have prime number of characters.
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result_words = [word for word in words if is_prime(len(word))]
    return ' '.join(result_words)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    return x if is_prime(n) else y

